from copy import deepcopy


def merge_profile(profile, updates):
    if not isinstance(profile, dict) or not isinstance(updates, dict):
        raise TypeError("profile and updates must be dictionaries")
    if any(not isinstance(key, str) for key in profile):
        raise TypeError("profile keys must be strings")
    if any(not isinstance(key, str) for key in updates):
        raise TypeError("update keys must be strings")

    result = profile
    for key, value in updates.items():
        result[key] = deepcopy(value)
    return result
